// VIDEOS의 모든 keywords 자동 카운트 → 카테고리 매핑 → 빈도순 상위 32개
const POPULAR_CATEGORIES = { "피부고민":[], "리프팅":[], "스킨부스터":[], "홈케어":[], "피부상식":[] };
const KEYWORD_CATEGORY = {};
(function () {
  const counts = {};
  for (const v of VIDEOS) {
    for (const qa of v.qas) {
      for (const kw of (qa.keywords || [])) counts[kw] = (counts[kw] || 0) + 1;
    }
  }
  // 매핑 우선순위 (중복 매칭 시): 스킨부스터 > 리프팅 > 피부고민 > 홈케어 → 그 외 피부상식
  const priority = ["스킨부스터", "리프팅", "피부고민", "홈케어"];
  const buckets = { "피부고민":[], "리프팅":[], "스킨부스터":[], "홈케어":[], "피부상식":[] };
  for (const kw of Object.keys(counts)) {
    let chosen = null;
    for (const cat of priority) {
      if (CATEGORY_SETS[cat].has(kw)) { chosen = cat; break; }
    }
    if (!chosen) chosen = "피부상식";
    buckets[chosen].push([kw, counts[kw]]);
    KEYWORD_CATEGORY[kw] = chosen;
  }
  for (const cat of Object.keys(buckets)) {
    buckets[cat].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0], 'ko'));
    POPULAR_CATEGORIES[cat] = buckets[cat].slice(0, 32).map(x => x[0]);
  }
})();

// 평탄화된 인기 검색어 (호환성)
const POPULAR_QUERIES = Object.values(POPULAR_CATEGORIES).flat();

// 평탄화된 Q&A 배열 (검색 인덱스용)
const ALL_QAS = VIDEOS.flatMap(v =>
  v.qas.map(qa => ({
    ...qa,
    videoId: v.id,
    videoTopic: v.topic,
    youtubeId: v.youtubeId,
    youtubeUrl: v.youtubeUrl,
    uploadDate: v.uploadDate,
  }))
);

// HOT (인기글 20개) — 카운트 누적 전이라 임시 임의 20개.
// 좋아요/조회수 충분히 쌓이면 fetch_hot.py 실행으로 진짜 인기 글로 자동 갱신.
const HOT_IDS = new Set([102, 201, 202, 203, 204, 301, 302, 303, 304, 401, 402, 403, 404, 3604, 21401, 26101]);

// 원장님 Pick (원장별 1~3개) — 최근 6개월 + 쥬브젠/힐로웨이브/올타이트/얼굴형/스컬트라 키워드 위주로 선정
const PICK_IDS_BY_DOCTOR = {
  "권수현": [101, 1103, 21502],
  "정한미": [604, 12501, 21801],     // 801(중복 토픽) → 12501 (스컬트라 5년 동안)
  "이도영": [203, 204, 20804],
  "박효진": [502, 19903, 21703],
  "김수형": [304, 1902],
  "김종식": [3002, 20802, 21503],
  "고혜림": [1303, 21201, 21204],
  "배정민": [3501],
  "강현진": [24301],
};
const PICK_IDS = new Set(Object.values(PICK_IDS_BY_DOCTOR).flat());

if (typeof window !== 'undefined') {
  window.PBTT = { DOCTORS, VIDEOS, SYNONYMS, POPULAR_QUERIES, POPULAR_CATEGORIES, KEYWORD_CATEGORY, ALL_QAS, HOT_IDS, PICK_IDS, PICK_IDS_BY_DOCTOR };
}
